issue_context.body:
### Expected behavior

I am trying to handle `javax.net.ssl.SSLHandshakeException` in `ApplicationProtocolNegotiationHandler`.

Here is the code:
```java
        @Override
        protected void handshakeFailure(ChannelHandlerContext ctx, Throwable cause) {
            System.err.println(cause.getMessage());
        }

        @Override
        public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
            System.err.println(cause.getMessage());
        }
```

I am able to print Throwable message but exception is still getting thrown with full stack trace, Am I doing it wrong?

### Netty version
4.1.50.Final
### JVM version (e.g. `java -version`)
openjdk version "11.0.5" 2019-10-15 LTS

### OS version (e.g. `uname -a`)
Windows 10 Pro for Workstations x64

comments:
```java
class ServerInitializer extends ChannelInitializer<SocketChannel> {

    protected void initChannel(SocketChannel socketChannel) {
        socketChannel.pipeline()
                .addLast(new SniHandler(/*My Custom SNI Mappings*/), new ALPNHandler());
    }

    @Override
    public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
        System.err.println(cause.getMessage());
        ctx.close();
    }

    private static class ALPNHandler extends ApplicationProtocolNegotiationHandler {

        private ALPNHandler() {
            super(ApplicationProtocolNames.HTTP_1_1);
        }

        @Override
        protected void configurePipeline(ChannelHandlerContext ctx, String protocol) {
            if (protocol.equalsIgnoreCase(ApplicationProtocolNames.HTTP_2)) {
                Http2Connection connection = new DefaultHttp2Connection(true);

                InboundHttp2ToHttpAdapter listener = new InboundHttp2ToHttpAdapterBuilder(connection)
                        .propagateSettings(false)
                        .validateHttpHeaders(true)
                        .maxContentLength(1024 * 100)
                        .build();

                HttpToHttp2ConnectionHandler http2Handler = new HttpToHttp2ConnectionHandlerBuilder()
                        .frameListener(new DelegatingDecompressorFrameListener(connection, listener))
                        .connection(connection)
                        .build();

                ctx.pipeline().addLast(http2Handler,
                        new HttpObjectAggregator(1024 * 100, true),
                        new HttpContentDecompressor(),
                        new HttpContentCompressor(6, 15, 8, 200),
                        new HTTPHandler(true));
            } else if (protocol.equalsIgnoreCase(ApplicationProtocolNames.HTTP_1_1)) {
                ctx.pipeline().addLast(
                        new HttpServerCodec(),
                        new HttpObjectAggregator(1024 * 100, true),
                        new HttpContentDecompressor(),
                        new HttpContentCompressor(6, 15, 8, 200),
                        new HTTPHandler(false));
            } else {
                System.err.println("Unknown Protocol: " + protocol);
            }
        }

        @Override
        protected void handshakeFailure(ChannelHandlerContext ctx, Throwable cause) {
            System.err.println(cause.getMessage());
            ctx.close();
        }

        @Override
        public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
            System.err.println(cause.getMessage());
            ctx.close();
        }
    }
}
